public class ConfigValidator : AbstractValidator<Config> {
    public ConfigValidator() {
        RuleFor(c => c.Host).NotEmpty();                              // contramap onto a field
        RuleFor(c => c.Port).InclusiveBetween(1, 65535);
        RuleFor(c => c.Proxy).SetValidator(new ProxyValidator());     // divide: nested rules
        When(c => c.UseTls, () => RuleFor(c => c.Cert).NotEmpty());   // choose
    }
}
